import unittest
from vm.interpreter import BytecodeVM

class TestVM(unittest.TestCase):
    def test_arithmetic(self):
        vm = BytecodeVM()
        # (3 + 4) * 2 = 14
        prog = [('PUSH', 3), ('PUSH', 4), ('ADD',), ('PUSH', 2), ('MUL',), ('HALT',)]
        self.assertEqual(vm.execute(prog), 14)

if __name__ == '__main__': unittest.main()

