class BytecodeVM:
    def __init__(self):
        self.stack = []

    def execute(self, bytecode: list[tuple[str, ...]]) -> int:
        pc = 0
        while pc < len(bytecode):
            op = bytecode[pc]
            cmd = op[0]
            if cmd == 'PUSH':
                self.stack.append(op[1])
            elif cmd == 'POP':
                self.stack.pop()
            elif cmd == 'ADD':
                b, a = self.stack.pop(), self.stack.pop()
                self.stack.append(a + b)
            elif cmd == 'SUB':
                b, a = self.stack.pop(), self.stack.pop()
                self.stack.append(a - b)
            elif cmd == 'MUL':
                b, a = self.stack.pop(), self.stack.pop()
                self.stack.append(a * b)
            elif cmd == 'HALT':
                break
            pc += 1
        return self.stack[-1] if self.stack else 0
